description:
Lines in a `requirements.txt` look like `requests>=2.31,<3` or `rich==13.7.1`. Write `parse_requirement(line)` that returns `(name, conditions)`:

- `name` is lower-case, with `_` and `.` turned into `-` (so `Typing_Extensions` becomes `typing-extensions`);
- `conditions` is a list of `(operator, version)` pairs in order; the operators are `==`, `!=`, `>=`, `<=`, `>`, `<` and `~=`;
- spaces anywhere are ignored, a `#` starts a comment, and an empty line (after removing the comment) gives `None`;
- anything else raises `ValueError`.

solution.solution.py:
import re

_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*")
_COND = re.compile(r"(==|!=|>=|<=|~=|>|<)([0-9][0-9A-Za-z.*+!-]*)")


def parse_requirement(line):
    text = line.split("#", 1)[0].replace(" ", "").replace("\t", "")
    if not text:
        return None
    m = _NAME.match(text)
    if not m:
        raise ValueError(f"no package name in {line!r}")
    name = re.sub(r"[._]", "-", m.group()).lower()
    rest = text[m.end():]
    conditions = []
    if rest:
        for part in rest.split(","):
            c = _COND.fullmatch(part)
            if not c:
                raise ValueError(f"bad version condition {part!r}")
            conditions.append((c.group(1), c.group(2)))
    return (name, conditions)

unitTests:
@test("a name with two conditions")
def _():
    check_eq(parse_requirement("requests>=2.31,<3"), ("requests", [(">=", "2.31"), ("<", "3")]))

@test("an exact pin")
def _():
    check_eq(parse_requirement("rich==13.7.1"), ("rich", [("==", "13.7.1")]))

@test("names are normalised")
def _():
    check_eq(parse_requirement("Typing_Extensions"), ("typing-extensions", []))
    check_eq(parse_requirement("zope.interface ~= 6.0"), ("zope-interface", [("~=", "6.0")]))

@test("spaces and comments")
def _():
    check_eq(parse_requirement("  numpy >= 1.26 , != 1.26.1   # fast arrays"), ("numpy", [(">=", "1.26"), ("!=", "1.26.1")]))
    check_eq(parse_requirement("# only a comment"), None)
    check_eq(parse_requirement(""), None)

@test("bad lines")
def _():
    for bad in ["requests>>2", ">=1.0", "requests=2", "requests>=2,"]:
        check_raises(ValueError, parse_requirement, bad)

